<template><div class="modal-backdrop chat-modal-backdrop"><div class="glass-modal document-picker"><div class="modal-heading"><h3>My documents</h3><IconButton icon="cancel" label="Close" @click="$emit('close')"/></div><div class="search-box"><span>⌕</span><input v-model="q" placeholder="Search documents" @input="load(1)"/></div><div v-if="loading" class="state-message">Loading…</div><div v-else class="picker-list"><label v-for="doc in result.items" :key="doc.id" class="picker-row"><input type="checkbox" :checked="selected.includes(doc.id)" :disabled="!selected.includes(doc.id)&&totalSelected>=maxSelected" @change="toggle(doc.id)"/><span><b>{{doc.fileName}}</b><small>{{formatSize(doc.sizeBytes)}}</small></span></label><p v-if="!result.items?.length" class="state-message">No documents found.</p></div><div class="pagination"><span>{{totalSelected}} / {{maxSelected}} selected</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div><div class="modal-actions"><IconButton icon="cancel" label="Cancel" @click="$emit('close')"/><IconButton icon="publish" label="Attach selected documents" @click="$emit('select',selected,names)"/></div></div></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{platformApi}from'@/services/platform';import IconButton from'@/components/ui/IconButton.vue';const props=withDefaults(defineProps<{modelValue:string[];maxSelected?:number}>(),{maxSelected:5});const emit=defineEmits<{close:[];select:[ids:string[],names:Record<string,string>]}>();const q=ref(''),loading=ref(false),result=ref<any>({items:[]}),selected=ref<string[]>([...props.modelValue]),totalSelected=computed(()=>selected.value.length),names=ref<Record<string,string>>({});async function load(page=1){loading.value=true;try{result.value=(await platformApi.documents(page,q.value)).data;for(const doc of result.value.items||[])names.value[doc.id]=doc.fileName}finally{loading.value=false}}function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}function formatSize(n:number){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`}onMounted(()=>load());</script>
